        .clk(clk),
        .areset(areset),
        .in(in),
        .out(out)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to check expected output
    task check_output(input expected_out);
        begin
            #1; // small delay to let combinational/sequential update settle
            if (out !== expected_out) begin
                $display("Time %0t: Mismatch! in=%b, expected out=%b, got out=%b", $time, in, expected_out, out);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        in = 0;

        // Test 1: Asynchronous Reset Test
        // Assert reset asynchronously and check state B (out = 1)
        areset = 1;
        #3;
        if (out !== 1'b1) begin
            $display("Time %0t: Async reset fail! Expected out=1, got out=%b", $time, out);
            errors = errors + 1;
        end

        // Deassert reset
        areset = 0;
        #2;
        // State should remain B (out = 1) immediately after reset deassertion
        check_output(1'b1);

        // Test State Transition Graph (Moore FSM):
        // States:
        // B (out = 1): --0--> A, --1--> B
        // A (out = 0): --0--> B, --1--> A

        // Current state: B (out = 1)
        // Apply input = 0 -> should transition to A (out = 0) on next clock edge
        in = 0;
        @(posedge clk);
        check_output(1'b0); // Now in state A (out = 0)

        // Current state: A (out = 0)
        // Apply input = 1 -> should transition to A (out = 0) on next clock edge
        in = 1;
        @(posedge clk);
        check_output(1'b0); // Stays in state A (out = 0)

        // Current state: A (out = 0)
        // Apply input = 0 -> should transition to B (out = 1) on next clock edge
        in = 0;
        @(posedge clk);
        check_output(1'b1); // Now in state B (out = 1)

        // Current state: B (out = 1)
        // Apply input = 1 -> should transition to B (out = 1) on next clock edge
        in = 1;
        @(posedge clk);
        check_output(1'b1); // Stays in state B (out = 1)

        // Test asynchronous reset recovery during operation
        in = 0;
        @(posedge clk); // moves to A (out = 0)
        check_output(1'b0);

        // Assert reset mid-operation
        areset = 1;
        #2;
        if (out !== 1'b1) begin
            $display("Time %0t: Mid-operation async reset fail! Expected out=1, got out=%b", $time, out);
            errors = errors + 1;
        end

        areset = 0;
        #3;
        check_output(1'b1); // Should be back in state B

        // Final Result Display
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
